import itertools

def check_n(n):
    def find_set(current_set, target_len, max_val):
        if len(current_set) == target_len:
            sums = sorted([current_set[i] + current_set[j] for i in range(target_len) for j in range(i+1, target_len)])
            if len(set(sums)) == len(sums):
                if sums[-1] - sums[0] == len(sums) - 1:
                    return current_set
            return None

        start_val = current_set[-1] + 1 if current_set else 0
        for v in range(start_val, max_val + 1):
            new_set = current_set + [v]
            sums = [new_set[i] + new_set[j] for i in range(len(new_set)) for j in range(i+1, len(new_set))]
            if len(set(sums)) < len(sums):
                continue
            if len(sums) >= 2:
                if max(sums) - min(sums) >= target_len * (target_len - 1) // 2:
                    # This v might be too large.
                    # But wait, min(sums) could increase if we change m_0.
                    # Let's just use a reasonable upper bound.
                    # m_{n-1} cannot be much larger than n^2/2.
                    if v > target_len * target_len:
                        break

            res = find_set(new_set, target_len, max_val)
            if res: return res
        return None

    return find_set([], n, n*n)

for n in range(3, 11):
    res = check_n(n)
    print(f"n={n}: {res}")

import itertools

def solve_n(n):
    # Find integers m_0 < m_1 < ... < m_{n-1} such that
    # {m_i + m_j} = {S, S+1, ..., S + n(n-1)//2 - 1}
    # We can fix m_0 = 0. Then m_1 is the smallest sum.
    # Let's iterate over m_1.
    for m1 in range(0, 20):
        # Now we need to find m_2, ..., m_{n-1}
        # Such that all m_i + m_j are in [m1, m1 + n(n-1)//2 - 1]
        # and are all distinct.
        def backtrack(current_set):
            if len(current_set) == n:
                sums = sorted([current_set[i] + current_set[j] for i in range(n) for j in range(i+1, n)])
                if len(set(sums)) == len(sums) and sums[-1] - sums[0] == len(sums) - 1:
                    return current_set
                return None

            # The next element m_k must be > m_{k-1}
            # Also m_k + m_0 must be <= m_1 + n(n-1)//2 - 1
            # And m_k + m_{k-1} must be <= m_1 + n(n-1)//2 - 1
            # Also m_k + m_0 must be > m_{k-1} + m_{k-2} (if k >= 3)
            # Wait, not necessarily. But m_k + m_0 must be one of the remaining sums.

            start_val = current_set[-1] + 1
            # Upper bound for m_k:
            # m_k + m_0 <= m_1 + n(n-1)//2 - 1
            # m_k <= m_1 + n(n-1)//2 - 1
            end_val = m1 + n*(n-1)//2

            for v in range(start_val, end_val + 1):
                new_sums = [v + x for x in current_set]
                # Check if these new sums are within range and distinct from existing sums
                existing_sums = {current_set[i] + current_set[j] for i in range(len(current_set)) for j in range(i+1, len(current_set))}
                if any(s in existing_sums for s in new_sums):
                    continue
                if any(s < m1 or s > m1 + n*(n-1)//2 - 1 for s in new_sums):
                    continue
                # Also check if the new sums themselves are distinct
                if len(set(new_sums)) < len(new_sums):
                    continue

                res = backtrack(current_set + [v])
                if res: return res
            return None

        res = backtrack([0, m1])
        if res: return res
    return None

for n in range(3, 7):
    print(f"n={n}: {solve_n(n)}")

def check_n_S(n, S):
    for m0 in range(-10, 10):
        for m1 in range(m0 + 1, 20):
            if m0 + m1 != S:
                continue
            def backtrack(current_set):
                if len(current_set) == n:
                    sums = sorted([current_set[i] + current_set[j] for i in range(n) for j in range(i+1, n)])
                    if len(set(sums)) == len(sums) and sums[-1] - sums[0] == len(sums) - 1:
                        return current_set
                    return None
                start_val = current_set[-1] + 1
                end_val = S + n*(n-1)//2 - current_set[0]
                for v in range(start_val, end_val + 1):
                    new_sums = [v + x for x in current_set]
                    existing_sums = {current_set[i] + current_set[j] for i in range(len(current_set)) for j in range(i+1, len(current_set))}
                    if any(s in existing_sums for s in new_sums): continue
                    if any(s < S or s > S + n*(n-1)//2 - 1 for s in new_sums): continue
                    if len(set(new_sums)) < len(new_sums): continue
                    res = backtrack(current_set + [v])
                    if res: return res
                return None
            res = backtrack([m0, m1])
            if res: return res
    return None

